mapper.select:
select cb.id,cb.update_time, cb.brand_id,cb.category_id,c.name as category_name,b.name as brand_name,b.logo
from category_brand cb left join category c on cb.category_id = c.id
left join brand b on cb.brand_id = b.id


        and cb.category_id = #{categoryId}


        and cb.brand_id = #{brandId}


order by cb.id desc
